mapper.select:
select t.context,t.status_cd,t.status_cd statusCd,t.store_id,t.store_id
storeId,t.contract_type_id,t.contract_type_id contractTypeId,t.template_id templateId,
t.template_name templateName, t.template_version templateVersion, t.template_desc templateDesc,
ifnull(t.use_count,0) useCount, ifnull(t.source_type,'online') sourceType, t.create_time createTime,
ifnull(ct.category,'2') category, ct.type_name contractTypeName
from contract_type_template t
left join contract_type ct on ct.contract_type_id = t.contract_type_id and ct.status_cd = '0' and ct.store_id =
t.store_id
where 1 =1

    and t.context= #{context}


    and t.status_cd= #{statusCd}


    and t.store_id= #{storeId}


    and t.contract_type_id= #{contractTypeId}


    and t.template_id= #{templateId}


    and ifnull(ct.category,'2') = #{category}


    and t.template_name like concat('%',#{templateNameLike},'%')

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update contract_type_template t set t.status_cd = #{statusCd}

    ,t.b_id = #{newBId}


    , t.context= #{context}


    , t.store_id= #{storeId}


    , t.contract_type_id= #{contractTypeId}


    , t.template_name= #{templateName}


    , t.template_version= #{templateVersion}


    , t.template_desc= #{templateDesc}


    , t.use_count= #{useCount}


    , t.source_type= #{sourceType}

where 1=1

    and t.template_id= #{templateId}

mapper.select:
select count(1) count
from contract_type_template t
left join contract_type ct on ct.contract_type_id = t.contract_type_id and ct.status_cd = '0' and ct.store_id =
t.store_id
where 1 =1

    and t.context= #{context}


    and t.status_cd= #{statusCd}


    and t.store_id= #{storeId}


    and t.contract_type_id= #{contractTypeId}


    and t.template_id= #{templateId}


    and ifnull(ct.category,'2') = #{category}


    and t.template_name like concat('%',#{templateNameLike},'%')

mapper.update:
update contract_type_template t set t.use_count = ifnull(t.use_count, 0) + 1
where 1 = 1

    and t.template_id = #{templateId}


    and t.store_id = #{storeId}
